/*
 * Phase 5 container-query whitelist member: the root is the query container
 * and the inner frame consumes it, so chrome morphs with the shell's own
 * inline size rather than the raw viewport.
 *
 * Three-end path: one `.cu-app-shell__nav` cell. Compact docks it to the
 * block-end and keeps it there while main scrolls; 48rem/80rem move the same
 * cell to the side column. Do not mount Sidebar + TabBar for that job — use
 * Navigation.
 *
 * Footer (`.cu-app-shell__footer`) placement is controlled by
 * `data-footer-placement` / `footerPlacement`:
 * - `shell`: dedicated grid row outside the main scrollport (legacy all-breakpoints).
 * - `main`: flows at the end of `__main` and scrolls with content.
 * - `auto` (default): compact → main flow; ≥48rem → shell chrome. Dual hosts
 *   swap via container query (`--flow` / `--chrome`); display:none collapses
 *   empty grid rows — do not rewrite the shell grid from consumer CSS.
 *
 * Prefer wrapping attribution in the `Footer` component.
 *
 * Legacy `sidebar` / `tab-bar` slots remain for specialized single-form chrome.
 * Nested previews must override block-size / max-block-size. The shell fills
 * its parent (html/body/#root at 100%, or the remaining flex row under demo
 * chrome). Do not lock min-block-size to 100dvh — that overflows any parent
 * shorter than the viewport and clips the compact nav off-screen.
 *
 * Height chain: ThemeProvider / ToastProvider are fragment-like. AppShell
 * exposes data-cu-shell so `#root > [data-cu-shell]` / `#app > [data-cu-shell]`
 * can fill when needed. Prefer ToastProvider fill, or rely on AppShell as a
 * direct percentage-height child of #root/#app.
 *
 * Edge flush: the shell root is edge-to-edge inside its parent (inline-size
 * 100%, no default margin/padding/radius). Gray viewport gutters are almost
 * always a consumer max-width/#app wrapper or missing html/body margin:0 —
 * not AppShell chrome. `__main` padding is content inset only.
 */
.cu-app-shell {
  box-sizing: border-box;
  container-name: app-shell;
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  border-radius: 0;
  inline-size: 100%;
  min-inline-size: 0;
  max-inline-size: 100%;
  block-size: 100%;
  min-block-size: 0;
  max-block-size: 100%;
  overflow: hidden;
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
}

.cu-app-shell__frame {
  display: grid;
  flex: 1 1 0;
  grid-template-areas:
    "header"
    "main";
  grid-template-columns: 1fr;
  grid-template-rows: auto minmax(0, 1fr);
  block-size: 100%;
  min-block-size: 0;
  max-block-size: 100%;
  overflow: hidden;
}

.cu-app-shell:has(.cu-app-shell__footer--chrome) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "footer";
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "nav";
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.cu-app-shell:has(.cu-app-shell__nav):has(.cu-app-shell__footer--chrome) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "footer"
    "nav";
  grid-template-rows: auto minmax(0, 1fr) auto auto;
}

.cu-app-shell:has(.cu-app-shell__tab-bar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "tabbar";
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.cu-app-shell:has(.cu-app-shell__tab-bar):not(:has(.cu-app-shell__nav)):has(.cu-app-shell__footer--chrome)
  .cu-app-shell__frame {
  grid-template-areas:
    "header"
    "main"
    "footer"
    "tabbar";
  grid-template-rows: auto minmax(0, 1fr) auto auto;
}

.cu-app-shell__header {
  grid-area: header;
  position: sticky;
  inset-block-start: 0;
  z-index: 8;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  background: var(
    --cu-color-background-translucent,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  border-block-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-app-shell__header:has(.cu-navigation-title),
.cu-app-shell__header:has(.cu-navigation-bar) {
  padding-block: 0;
  padding-inline: 0;
}

.cu-app-shell__nav {
  grid-area: nav;
  position: sticky;
  inset-block-end: 0;
  z-index: 9;
  flex-shrink: 0;
}

.cu-app-shell__sidebar {
  display: none;
  grid-area: sidebar;
  padding-block: var(--cu-space-4, var(--cu-space-3));
  padding-inline: var(--cu-space-3);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-app-shell__main {
  grid-area: main;
  display: flex;
  flex-direction: column;
  min-block-size: 0;
  min-inline-size: 0;
  padding-block: var(--cu-space-5, var(--cu-space-3));
  padding-inline: var(--cu-space-5, var(--cu-space-3));
  overflow-x: hidden;
  overflow-y: auto;
  /* auto: short content must not reserve a visible gutter (stable did). */
  scrollbar-gutter: auto;
  contain: layout style;
  overscroll-behavior: contain;
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
}

/*
 * Scroll owner contract (unique):
 * - WorkspaceSplit scrollMode=shell|none (default shell): grow with content;
 *   `__main` remains the scrollport.
 * - WorkspaceSplit scrollMode=panes, or direct ScrollPane: child fills;
 *   `__main` stops scrolling so panes / ScrollPane own overflow.
 */
.cu-app-shell__main > .cu-workspace-split {
  flex: 1 0 auto;
  min-block-size: 100%;
  min-inline-size: 0;
  block-size: auto;
  max-block-size: none;
}

.cu-app-shell__main > .cu-workspace-split[data-scroll-mode='panes'],
.cu-app-shell__main > .cu-scroll-pane {
  flex: 1 1 0;
  min-block-size: 0;
  min-inline-size: 0;
  block-size: auto;
  max-block-size: 100%;
}

.cu-app-shell__main:has(> .cu-workspace-split[data-scroll-mode='panes']),
.cu-app-shell__main:has(> .cu-scroll-pane) {
  overflow-y: hidden;
  scrollbar-gutter: auto;
}

.cu-app-shell__footer {
  flex-shrink: 0;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-5, var(--cu-space-3));
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
  /* No default fill — consumers theme if they want a surface. */
  background: transparent;
  border-block-start: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-app-shell__footer--chrome {
  grid-area: footer;
  z-index: 7;
  padding-block-end: max(var(--cu-space-2), env(safe-area-inset-bottom, 0px));
}

.cu-app-shell__footer--flow {
  margin-block-start: var(--cu-space-5, var(--cu-space-3));
  padding-block-end: var(--cu-space-2);
}

/* auto (default): compact → flow in main; wide → shell chrome. */
.cu-app-shell[data-footer-placement='auto'] .cu-app-shell__footer--chrome {
  display: none;
}

.cu-app-shell[data-footer-placement='auto'] .cu-app-shell__footer--flow {
  display: block;
}

.cu-app-shell[data-footer-placement='shell'] .cu-app-shell__footer--flow {
  display: none;
}

.cu-app-shell[data-footer-placement='main'] .cu-app-shell__footer--chrome {
  display: none;
}

/* Compact nav / tabBar owns the home-indicator inset; chrome footer sits above them. */
.cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__footer--chrome,
.cu-app-shell:has(.cu-app-shell__tab-bar) .cu-app-shell__footer--chrome {
  padding-block-end: var(--cu-space-2);
}

.cu-app-shell__tab-bar {
  grid-area: tabbar;
  position: sticky;
  inset-block-end: 0;
  z-index: 9;
}

.cu-app-shell__tab-bar .cu-tab-bar {
  position: relative;
  inset: auto;
  z-index: 2;
}

/* 48rem == breakpoint.tablet, 80rem == breakpoint.desktop (tokens/src/core/breakpoint.json).
 * Named `app-shell` — never rely on the nearest anonymous container (Navigation
 * is also a container; descendants under __nav must still key off the shell). */
@container app-shell (min-width: 48rem) {
  .cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__nav):has(.cu-app-shell__footer--chrome) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main"
      "nav footer";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)):has(.cu-app-shell__footer--chrome)
    .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main"
      "sidebar footer";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav))
    .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main"
      "tabbar tabbar";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)):has(
      .cu-app-shell__footer--chrome
    )
    .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main"
      "sidebar footer"
      "tabbar tabbar";
    grid-template-columns: 12rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto auto;
  }

  .cu-app-shell__sidebar {
    display: block;
    position: sticky;
    inset-block-start: 0;
    inset-inline-start: 0;
    align-self: stretch;
    min-block-size: 0;
    overflow: auto;
  }

  .cu-app-shell__nav {
    position: sticky;
    inset-block-start: 0;
    inset-inline-start: 0;
    inset-block-end: auto;
    align-self: stretch;
    min-block-size: 0;
    /* Scroll lives in Navigation __list — do not scroll the whole rail. */
    overflow: hidden;
  }

  /* auto: wide shell uses chrome footer; hide the in-main copy. */
  .cu-app-shell[data-footer-placement='auto'] .cu-app-shell__footer--chrome {
    display: block;
  }

  .cu-app-shell[data-footer-placement='auto'] .cu-app-shell__footer--flow {
    display: none;
  }

  /* Tablet collapsed rail: shrink the nav column to icon width. */
  .cu-app-shell:has(.cu-navigation--collapsed) .cu-app-shell__frame {
    grid-template-columns: 4.5rem minmax(0, 1fr);
  }
}

@container app-shell (min-width: 80rem) {
  .cu-app-shell:has(.cu-app-shell__nav) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main";
    grid-template-columns: 16rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__nav):has(.cu-app-shell__footer--chrome) .cu-app-shell__frame {
    grid-template-areas:
      "nav header"
      "nav main"
      "nav footer";
    grid-template-columns: 16rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  /* Desktop keeps the persistent sidebar width even if collapsed was left on. */
  .cu-app-shell:has(.cu-navigation--collapsed) .cu-app-shell__frame {
    grid-template-columns: 16rem minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)) .cu-app-shell__frame,
  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav))
    .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main";
    grid-template-columns: 16rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .cu-app-shell:has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)):has(.cu-app-shell__footer--chrome)
    .cu-app-shell__frame,
  .cu-app-shell:has(.cu-app-shell__tab-bar):has(.cu-app-shell__sidebar):not(:has(.cu-app-shell__nav)):has(
      .cu-app-shell__footer--chrome
    )
    .cu-app-shell__frame {
    grid-template-areas:
      "sidebar header"
      "sidebar main"
      "sidebar footer";
    grid-template-columns: 16rem minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .cu-app-shell__tab-bar {
    display: none;
  }
}
